/*
-- Query: SELECT * FROM kkpl.inventory
LIMIT 0, 1000

-- Date: 2025-06-17 18:06
*/
CREATE TABLE `inventory` (
  `id` int NOT NULL AUTO_INCREMENT,
  `productId` varchar(50) NOT NULL,
  `productName` varchar(100) NOT NULL,
  `unitPrice` decimal(10,2) DEFAULT NULL,
  `quantityInStock` int NOT NULL,
  `fabricType` varchar(50) NOT NULL,
  `gsm` int DEFAULT NULL,
  `width` decimal(5,2) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `pattern` varchar(50) DEFAULT NULL,
  `unitOfMeasure` varchar(20) DEFAULT NULL,
  `reorderLevel` int DEFAULT NULL,
  `lastRestockedDate` date DEFAULT NULL,
  `storageLocation` varchar(100) DEFAULT NULL,
  `fabricFinish` varchar(50) DEFAULT NULL,
  `applicationArea` varchar(100) DEFAULT NULL,
  `qualityStatus` varchar(20) DEFAULT NULL,
  `remarks` text,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedBy` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `productCode` (`productId`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


